func domainNum(base string, n int) string {
	b := []byte(base)
	b = append(b, '-')
	if n < 10 {
		b = append(b, '0'+byte(n))
	} else {
		b = append(b, '0'+byte(n/10))
		b = append(b, '0'+byte(n%10))
	}
	return string(b)
}
